#include "Host.h"
#include <iostream>
using namespace juce;
void require(bool ok,const char* message){if(!ok){std::cerr<<"FAIL: "<<message<<'\n';std::exit(1);}}
int main(int argc,char** argv){ScopedJuceInitialiser_GUI gui;
 {auto pStorage = std::make_unique<DualProcessor>();
 auto& p = *pStorage;
 MidiBuffer input,ma,mb;input.addEvent(MidiMessage::noteOn(1,60,.8f),17);p.routeMidi(input,ma,mb);require(ma.getNumEvents()==1&&mb.getNumEvents()==1,"layer fans out to both");p.write("routing",1);p.write("split",72);input.clear();input.addEvent(MidiMessage::noteOff(1,60),21);p.routeMidi(input,ma,mb);require(ma.getNumEvents()==1&&mb.getNumEvents()==1,"held note ownership survives changed split");input.clear();input.addEvent(MidiMessage::noteOn(1,71,.8f),3);input.addEvent(MidiMessage::noteOn(1,72,.8f),4);p.routeMidi(input,ma,mb);require(ma.getNumEvents()==1&&mb.getNumEvents()==1,"split boundary routes A below and B at split");require((*ma.begin()).samplePosition==3&&(*mb.begin()).samplePosition==4,"MIDI sample offsets preserved");p.write("a.high",60);input.clear();input.addEvent(MidiMessage::noteOn(1,61,.7f),0);p.routeMidi(input,ma,mb);require(ma.isEmpty()&&mb.isEmpty(),"split intersects per-engine note range");p.write("a.channel",2);input.clear();input.addEvent(MidiMessage::noteOn(1,40,.7f),0);p.routeMidi(input,ma,mb);require(ma.isEmpty()&&mb.isEmpty(),"channel filter");input.clear();input.addEvent(MidiMessage::controllerEvent(1,64,127),0);p.routeMidi(input,ma,mb);require(ma.getNumEvents()==1&&mb.getNumEvents()==1,"controllers reach both to release tails");}
 for(int engine=0;engine<2;++engine){auto hostStorage = std::make_unique<DualProcessor>();
 auto& host = *hostStorage;
 std::unique_ptr<AudioProcessor> reference=engine==0?std::unique_ptr<AudioProcessor>(new SynthAProcessor):std::unique_ptr<AudioProcessor>(new PrismProcessor);host.write("routing",float(engine+2));host.write("a.gain",0);host.write("b.gain",0);host.write("master",0);host.write("glue",0);host.prepareToPlay(48000,256);reference->setRateAndBufferSizeDetails(48000,256);reference->prepareToPlay(48000,256);auto visible=std::unique_ptr<AudioProcessorEditor>(host.createEditor());AudioBuffer<float> output(2,256),raw(2,256);std::array<std::array<float,4>,2> delay{};int head=0;double energy=0;for(int block=0;block<200;++block){if(block%40==0)dynamic_cast<DualEditor*>(visible.get())->select((block/40)%2);MidiBuffer midi,copy;if(block==0){midi.addEvent(MidiMessage::noteOn(1,60,.8f),17);midi.addEvent(MidiMessage::noteOn(1,67,.7f),80);}if(block==120)midi.addEvent(MidiMessage::allNotesOff(1),9);copy=midi;host.processBlock(output,midi);reference->processBlock(raw,copy);for(int n=0;n<256;++n){for(int c=0;c<2;++c){float expected=raw.getSample(c,n);if(engine==1){float aligned=delay[size_t(c)][size_t(head)];delay[size_t(c)][size_t(head)]=expected;expected=aligned;}if(output.getSample(c,n)!=expected){std::cerr<<"engine "<<engine<<" block "<<block<<" sample "<<n<<" got "<<output.getSample(c,n)<<" expected "<<expected<<" delta "<<(output.getSample(c,n)-expected)<<" gains "<<host.value("a.gain")<<" "<<host.value("b.gain")<<" "<<host.value("master")<<"\n";require(false,"unity/bypassed output exactly equals original engine (B aligned by4samples)");}energy+=expected*expected;}head=(head+1)%4;}}require(energy>1.e-6,"identity comparison has signal");}
 auto pStorage = std::make_unique<DualProcessor>();
 auto& p = *pStorage;
 p.a.loadPreset(3);p.b.selectFactory(4);p.write("split",65);p.write("a.gain",-3);p.write("b.mute",1);p.write("room",.83f);p.panel.store(1);MemoryBlock state;p.getStateInformation(state);auto recalledStorage = std::make_unique<DualProcessor>();
 auto& recalled = *recalledStorage;
 recalled.setStateInformation(state.getData(),int(state.getSize()));require(recalled.value("split")==65&&recalled.value("b.mute")==1&&std::abs(recalled.value("room")-.83f)<1.e-6,"host state recall");require(recalled.a.patchName()==p.a.patchName()&&recalled.b.title()==p.b.title()&&recalled.panel.load()==1,"both complete engine states and view recall");
 auto* child=p.b.parameters.getParameter("osc1.pos");AudioProcessorParameter* proxy=nullptr;for(auto* parameter:p.getParameters())if(auto* id=dynamic_cast<AudioProcessorParameterWithID*>(parameter))if(id->paramID=="B.osc1.pos")proxy=parameter;require(proxy!=nullptr,"prefixed automation exists");proxy->setValue(.7f);require(std::abs(child->getValue()-.7f)<1.e-6,"host automation forwards to original parameter");p.b.write("osc1.pos",.2f);require(std::abs(proxy->getValue()-child->getValue())<1.e-6,"original UI forwards parameter value");
 p.prepareToPlay(48000,256);p.write("b.mute",0);p.write("glue",1);p.write("eq",1);p.write("width",1.5f);p.write("low",12);p.write("air",12);AudioBuffer<float> output(2,256);double energy=0;for(int block=0;block<600;++block){MidiBuffer midi;if(block==0)for(int note:{48,55,60,67})midi.addEvent(MidiMessage::noteOn(1,note,.8f),0);if(block==180)midi.addEvent(MidiMessage::allNotesOff(1),0);p.processBlock(output,midi);for(int c=0;c<2;++c)for(int n=0;n<256;++n){float v=output.getSample(c,n);require(std::isfinite(v),"master effects finite");energy+=v*v;}}require(energy>1.e-6,"layer and glue render");
 {auto mutedStorage = std::make_unique<DualProcessor>();
 auto& muted = *mutedStorage;
 muted.prepareToPlay(48000,256);muted.write("a.mute",1);muted.write("b.mute",1);AudioBuffer<float> test(2,256);for(int i=0;i<16;++i){MidiBuffer midi;if(i==0)midi.addEvent(MidiMessage::noteOn(1,60,.8f),0);muted.processBlock(test,midi);}require(test.getMagnitude(0,256)==0&&muted.a.voicesPlaying.load()>0&&muted.b.voices.load()>0,"mute fades output while both engines keep running");muted.write("b.mute",0);double signal=0;for(int i=0;i<16;++i){MidiBuffer midi;muted.processBlock(test,midi);signal+=test.getMagnitude(0,256);}require(signal>1.e-5&&muted.peaks[0].load()==0,"unmuting reveals held B without retriggering A or B");}
 if(argc>1){p.write("low",0);p.write("air",0);p.write("width",1);p.write("eq",0);p.write("glue",0);File folder=File::getCurrentWorkingDirectory().getChildFile(argv[1]);folder.createDirectory();auto editor=std::unique_ptr<AudioProcessorEditor>(p.createEditor());for(int panel=0;panel<2;++panel){dynamic_cast<DualEditor*>(editor.get())->select(panel);for(int width:{1280,1600}){editor->setSize(width,width*840/1600);auto snapshot=editor->createComponentSnapshot(editor->getLocalBounds(),true);auto stream=folder.getChildFile("Dual-Synth-"+String(panel==0?"A":"B")+"-"+String(width)+".png").createOutputStream();stream->setPosition(0);stream->truncate();PNGImageFormat png;require(png.writeImageToStream(snapshot,*stream),"actual host editor snapshot");}}}
 std::cout<<"PASS: layer/split/ranges/channels, note ownership, sample offsets, output mutes preserve voices, both engines exact unity output (B four-sample alignment), complete host+engine recall, prefixed automation, master effects finite, editor lifecycle.\n";
}
